create or replace function public.moderator_decide_application(
  p_application_id uuid,
  p_expected_updated_at timestamptz,
  p_decision text,
  p_internal_note text default null,
  p_applicant_message text default null
)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_moderator();
  current_row public.applications;
  target_status public.application_status;
begin
  if p_decision not in ('request_changes', 'reject') then
    raise exception using errcode = '22023', message = 'Unsupported application decision';
  end if;
  if p_decision = 'request_changes' and coalesce(length(trim(p_applicant_message)), 0) = 0 then
    raise exception using errcode = '22023', message = 'Applicant message is required';
  end if;
  if length(coalesce(p_internal_note, '')) > 5000 or length(coalesce(p_applicant_message, '')) > 5000 then
    raise exception using errcode = '22023', message = 'Moderation text is too long';
  end if;

  select * into current_row from public.applications
  where id = p_application_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'Application not found'; end if;
  if p_expected_updated_at is null or current_row.updated_at is distinct from p_expected_updated_at then
    raise exception using errcode = '40001', message = 'Application changed after review';
  end if;
  if current_row.status not in ('new','screening','info_required','changes_requested','call_required','call_scheduled') then
    raise exception using errcode = '22023', message = 'Application transition is not allowed';
  end if;

  target_status := case when p_decision = 'request_changes' then 'changes_requested'::public.application_status else 'rejected'::public.application_status end;
  update public.applications
  set status = target_status,
      internal_notes = nullif(trim(p_internal_note), ''),
      applicant_message = case when target_status = 'changes_requested' then trim(p_applicant_message) else null end
  where id = current_row.id;

  perform private.append_privileged_audit(
    actor, 'application', current_row.id,
    case when target_status = 'changes_requested' then 'changes_requested' else 'rejected' end,
    jsonb_build_object('before_status', current_row.status, 'after_status', target_status)
  );
