create or replace function public.apply_specialist_revision(
  revision_uuid uuid,
  approve boolean,
  note text default null
)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_moderator();
  current_row public.specialist_revisions;
  payload jsonb;
  offers jsonb;
  legacy_services text[];
  current_profile public.specialists;
begin
  if not approve and (coalesce(length(trim(note)), 0) = 0 or length(note) > 5000) then
    raise exception using errcode = '22023', message = 'A valid rejection comment is required';
  end if;
  select * into current_row from public.specialist_revisions
  where id = revision_uuid for update;
  if not found then raise exception using errcode = 'P0002', message = 'Revision not found'; end if;
  if current_row.status <> 'pending' then
    raise exception using errcode = '22023', message = 'Revision has already been decided';
  end if;
  select * into current_profile from public.specialists
  where id = current_row.specialist_id and owner_id = current_row.owner_id for update;
  if not found then raise exception using errcode = '22023', message = 'Revision owner mismatch'; end if;
  payload := current_row.payload;

  if approve and (
    nullif(payload->>'avatar_path','') is distinct from current_profile.avatar_path
    or (payload ? 'gallery_paths' and array(select jsonb_array_elements_text(coalesce(payload->'gallery_paths','[]'::jsonb))) is distinct from current_profile.gallery_paths)
  ) then
    raise exception using errcode = '22023', message = 'Canonical server publication required for changed media';
  end if;

  if approve and payload->>'contract_version' = '2' then
    offers := payload->'work_offers';
    legacy_services := public.work_offer_titles(offers);
    update public.specialists set
      contract_version = 2,
      full_name = coalesce(nullif(payload->>'full_name',''), full_name),
      country = coalesce(nullif(payload->>'country',''), country),
      city = coalesce(nullif(payload->>'city',''), city),
      category_id = case when nullif(payload->>'category_id','') is null then category_id else (payload->>'category_id')::uuid end,
      additional_category_ids = coalesce(array(select jsonb_array_elements_text(coalesce(payload->'additional_category_ids','[]'::jsonb))::uuid), '{}'::uuid[]),
      specialization = nullif(payload->>'specialization',''),
      experience_years = (payload->>'experience_years')::integer,
      profile_summary = payload->>'profile_summary',
      short_description = payload->>'profile_summary',
      full_description = payload->>'full_description',
      help_topics = payload->'help_topics',
      work_offers = offers,
      services = legacy_services,
      service_mode = public.work_offer_mode(offers, service_mode),
      avatar_path = payload->>'avatar_path',
      status = 'published',
      published_at = coalesce(published_at, clock_timestamp()),
      updated_at = clock_timestamp()
    where id = current_row.specialist_id and owner_id = current_row.owner_id;
  elsif approve then
    update public.specialists set
      full_name = coalesce(nullif(payload->>'full_name',''), full_name),
      country = coalesce(nullif(payload->>'country',''), country),
      city = coalesce(nullif(payload->>'city',''), city),
      service_mode = coalesce(nullif(payload->>'service_mode',''), service_mode),
      category_id = case when nullif(payload->>'category_id','') is null then category_id else (payload->>'category_id')::uuid end,
      additional_category_ids = coalesce(array(select jsonb_array_elements_text(coalesce(payload->'additional_category_ids', to_jsonb(additional_category_ids)))::uuid), additional_category_ids),
      specialization = coalesce(nullif(payload->>'specialization',''), specialization),
      experience_years = case when nullif(payload->>'experience_years','') is null then experience_years else (payload->>'experience_years')::integer end,
      services = coalesce(array(select jsonb_array_elements_text(coalesce(payload->'services', to_jsonb(services)))), services),
      profile_summary = coalesce(nullif(payload->>'profile_summary',''), nullif(payload->>'short_description',''), profile_summary),
      short_description = coalesce(nullif(payload->>'short_description',''), short_description),
      full_description = coalesce(nullif(payload->>'full_description',''), full_description),
      help_topics = coalesce(payload->'help_topics', help_topics),
      work_offers = coalesce(payload->'work_offers', work_offers),
      public_contact = coalesce(nullif(payload->>'public_contact',''), public_contact),
      portfolio_links = coalesce(array(select jsonb_array_elements_text(coalesce(payload->'portfolio_links', to_jsonb(portfolio_links)))), portfolio_links),
      video_links = coalesce(array(select jsonb_array_elements_text(coalesce(payload->'video_links', to_jsonb(video_links)))), video_links),
      avatar_path = coalesce(nullif(payload->>'avatar_path',''), avatar_path),
      gallery_paths = coalesce(array(select jsonb_array_elements_text(coalesce(payload->'gallery_paths', to_jsonb(gallery_paths)))), gallery_paths),
      recommendations = coalesce(nullif(payload->>'recommendations',''), recommendations),
      status = 'published',
      published_at = coalesce(published_at, clock_timestamp()),
      updated_at = clock_timestamp()
    where id = current_row.specialist_id and owner_id = current_row.owner_id;
  end if;

  update public.specialist_revisions
  set status = case when approve then 'approved' else 'rejected' end,
      moderator_id = actor,
      moderator_comment = nullif(trim(note), ''),
      decided_at = clock_timestamp()
  where id = current_row.id;
  perform private.append_privileged_audit(
    actor, 'specialist_revision', current_row.id,
    case when approve then 'approved' else 'rejected' end,
    jsonb_build_object('before_status', current_row.status, 'after_status', case when approve then 'approved' else 'rejected' end)
  );
end;
$$;
