  actor uuid := private.require_current_admin_aal2();
  current_row public.applications;
begin
  select * into current_row from public.applications where id = p_application_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'Application not found'; end if;
  if current_row.status is distinct from p_expected_status then
    raise exception using errcode = '40001', message = 'Application state is stale';
  end if;
  if not (
    p_target_status = 'withdrawn' and current_row.status in ('new','screening','info_required','changes_requested','call_required','call_scheduled','rejected')
    or p_target_status = 'new' and current_row.status = 'withdrawn'
  ) then
    raise exception using errcode = '22023', message = 'Admin application transition is not allowed';
  end if;
  update public.applications set status = p_target_status where id = current_row.id;
  perform private.append_privileged_audit(
    actor, 'application', current_row.id,
    case when p_target_status = 'withdrawn' then 'archived' else 'restored_from_archive' end,
    jsonb_build_object('before_status', current_row.status, 'after_status', p_target_status)
  );
end;
$$;
