create or replace function private.assert_admin_profile_transition(
  p_before public.profile_status,
  p_after public.profile_status
)
returns void
language plpgsql
immutable
set search_path = pg_catalog
as $$
begin
  if p_before is not distinct from p_after then return; end if;
  if not (
    (p_before = 'published' and p_after in ('suspended','blocked','archived'))
    or (p_before = 'suspended' and p_after in ('published','blocked','archived'))
    or (p_before = 'blocked' and p_after in ('published','archived'))
    or (p_before = 'archived' and p_after = 'published')
  ) then
    raise exception using errcode = '22023', message = 'Admin profile transition is not allowed';
  end if;
end;
$$;
revoke all on function private.assert_admin_profile_transition(public.profile_status, public.profile_status)
  from public, anon, authenticated;

create or replace function public.admin_update_specialist_controls(
  p_specialist_id uuid,
  p_expected_status public.profile_status,
  p_target_status public.profile_status,
  p_identity_checked boolean,
  p_education_checked boolean,
  p_experience_checked boolean,
  p_qualifications_checked boolean,
  p_references_checked boolean,
  p_sources_checked integer
)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_admin_aal2();
  current_row public.specialists;
begin
  if p_sources_checked is null or p_sources_checked not between 0 and 999
     or p_identity_checked is null or p_education_checked is null
     or p_experience_checked is null or p_qualifications_checked is null
     or p_references_checked is null then
    raise exception using errcode = '22023', message = 'Verification facts are invalid';
  end if;
  select * into current_row from public.specialists where id = p_specialist_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'Specialist not found'; end if;
  if current_row.status is distinct from p_expected_status then
    raise exception using errcode = '40001', message = 'Specialist state is stale';
  end if;
  perform private.assert_admin_profile_transition(current_row.status, p_target_status);

  update public.specialists
  set status = p_target_status,
      published_at = case when p_target_status = 'published' then coalesce(published_at, clock_timestamp()) else published_at end
  where id = current_row.id;

  insert into public.verifications(
    specialist_id, identity_checked, education_checked, experience_checked,
    qualifications_checked, references_checked, sources_checked, checked_by, checked_at
  ) values (
    current_row.id, p_identity_checked, p_education_checked, p_experience_checked,
    p_qualifications_checked, p_references_checked, p_sources_checked, actor, clock_timestamp()
  )
  on conflict (specialist_id) do update set
    identity_checked = excluded.identity_checked,
    education_checked = excluded.education_checked,
    experience_checked = excluded.experience_checked,
    qualifications_checked = excluded.qualifications_checked,
    references_checked = excluded.references_checked,
    sources_checked = excluded.sources_checked,
    checked_by = excluded.checked_by,
    checked_at = excluded.checked_at;

  perform private.append_privileged_audit(
    actor, 'specialist', current_row.id, 'profile_and_verification_updated',
    jsonb_build_object('before_status', current_row.status, 'after_status', p_target_status, 'sources_checked', p_sources_checked)
  );
end;
$$;
revoke all on function public.admin_update_specialist_controls(uuid, public.profile_status, public.profile_status, boolean, boolean, boolean, boolean, boolean, integer)
  from public, anon, authenticated;
