  perform 1 from public.specialists where id = p_specialist_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'Specialist not found'; end if;
  if cardinality(selected) > 50 or cardinality(selected) <> (select count(distinct value) from unnest(selected) value) then
    raise exception using errcode = '22023', message = 'Badge selection is invalid';
  end if;
  if exists (
    select 1 from unnest(selected) value
    left join public.trust_badges badge on badge.id = value
    where badge.id is null or badge.assignment_type <> 'manual' or not badge.is_active
  ) then
    raise exception using errcode = '22023', message = 'Badge selection contains a disallowed badge';
  end if;
  delete from public.specialist_trust_badges
  where specialist_id = p_specialist_id and source = 'manual' and not (badge_id = any(selected));
  insert into public.specialist_trust_badges(specialist_id, badge_id, assigned_by, source, admin_note)
  select p_specialist_id, value, actor, 'manual', null from unnest(selected) value
  on conflict (specialist_id, badge_id) do nothing;
  perform private.append_privileged_audit(
    actor, 'specialist', p_specialist_id, 'trust_badges_updated',
    jsonb_build_object('manual_badge_count', cardinality(selected))
  );
end;
$$;
revoke all on function public.admin_set_manual_trust_badges(uuid, uuid[])
  from public, anon, authenticated;
grant execute on function public.admin_set_manual_trust_badges(uuid, uuid[])
  to authenticated;

create or replace function public.admin_update_site_content(p_content jsonb)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_admin_aal2();
  allowed_keys text[] := array[
    'brand_name','tagline','hero_title','hero_text','contact_email','about_text',
    'rules_intro','privacy_text','seo_title','seo_description'
  ];
begin
  if jsonb_typeof(p_content) is distinct from 'object'
     or not (p_content ?& allowed_keys)
     or exists (select 1 from jsonb_object_keys(p_content) key where not (key = any(allowed_keys))) then
    raise exception using errcode = '22023', message = 'Site content payload has unsupported fields';
  end if;
  update public.site_content set
    brand_name = p_content->>'brand_name', tagline = p_content->>'tagline',
    hero_title = p_content->>'hero_title', hero_text = p_content->>'hero_text',
    contact_email = p_content->>'contact_email', about_text = p_content->>'about_text',
    rules_intro = p_content->>'rules_intro', privacy_text = p_content->>'privacy_text',
    seo_title = p_content->>'seo_title', seo_description = p_content->>'seo_description',
    updated_by = actor
  where id = true;
  if not found then raise exception using errcode = 'P0002', message = 'Site content row not found'; end if;
  perform private.append_privileged_audit(actor, 'site_content', null, 'updated', jsonb_build_object('field_count', cardinality(allowed_keys)));
end;
$$;
revoke all on function public.admin_update_site_content(jsonb) from public, anon, authenticated;
grant execute on function public.admin_update_site_content(jsonb) to authenticated;

create or replace function public.admin_set_moderator_role(p_user_id uuid, p_role public.moderator_role default null)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_admin_aal2();
  previous_role public.moderator_role;
begin
  if p_user_id is null or p_user_id = actor then
    raise exception using errcode = '22023', message = 'Administrators cannot change their own role';
  end if;
  select role into previous_role from public.moderators where user_id = p_user_id for update;
  if p_role is null then
    delete from public.moderators where user_id = p_user_id;
  else
    insert into public.moderators(user_id, role) values (p_user_id, p_role)
    on conflict (user_id) do update set role = excluded.role;
  end if;
  perform private.append_privileged_audit(
    actor, 'moderator_membership', p_user_id, 'role_changed',
    jsonb_build_object('before_role', previous_role, 'after_role', p_role)
  );
end;
$$;
revoke all on function public.admin_set_moderator_role(uuid, public.moderator_role)
  from public, anon, authenticated;
grant execute on function public.admin_set_moderator_role(uuid, public.moderator_role)
  to authenticated;

create or replace function public.admin_upsert_category(
  p_category_id uuid,
  p_name text,
  p_slug text,
  p_group_name text,
  p_is_active boolean
)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_admin_aal2();
begin
  if p_category_id is null or coalesce(length(trim(p_name)),0) < 2
     or p_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or p_is_active is null then
    raise exception using errcode = '22023', message = 'Category payload is invalid';
  end if;
  insert into public.categories(id, name, slug, group_name, is_active)
  values (p_category_id, trim(p_name), p_slug, nullif(trim(p_group_name),''), p_is_active)
  on conflict (id) do update set
    name = excluded.name, slug = excluded.slug,
    group_name = excluded.group_name, is_active = excluded.is_active;
  perform private.append_privileged_audit(actor, 'category', p_category_id, 'upserted', jsonb_build_object('is_active', p_is_active));
end;
$$;
revoke all on function public.admin_upsert_category(uuid, text, text, text, boolean)
  from public, anon, authenticated;
grant execute on function public.admin_upsert_category(uuid, text, text, text, boolean)
  to authenticated;

create or replace function public.admin_delete_category(p_category_id uuid)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_admin_aal2();
begin
  perform 1 from public.categories where id = p_category_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'Category not found'; end if;
  delete from public.categories where id = p_category_id;
  perform private.append_privileged_audit(actor, 'category', p_category_id, 'deleted', '{}'::jsonb);
end;
$$;
revoke all on function public.admin_delete_category(uuid) from public, anon, authenticated;
grant execute on function public.admin_delete_category(uuid) to authenticated;

create or replace function public.admin_retry_email_notification(p_notification_id uuid)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  actor uuid := private.require_current_admin_aal2();
  current_status text;
begin
  select status into current_status from public.email_notifications
  where id = p_notification_id for update;
  if not found or current_status not in ('failed','cancelled') then
    raise exception using errcode = '22023', message = 'Notification is not retryable';
  end if;
  update public.email_notifications
  set status = 'pending', next_attempt_at = clock_timestamp(), last_error = null
  where id = p_notification_id;
  perform private.append_privileged_audit(actor, 'email_notification', p_notification_id, 'retry_requested', jsonb_build_object('before_status', current_status));
end;
$$;
revoke all on function public.admin_retry_email_notification(uuid)
  from public, anon, authenticated;
grant execute on function public.admin_retry_email_notification(uuid)
  to authenticated;

-- Wrap the existing SEC-001 service-only publication primitives so the
-- privileged actor and decision audit are committed in the same transaction.
create or replace function public.approve_application_with_canonical_media_v2(
  application_uuid uuid,
  reviewer_uuid uuid,
  expected_updated_at timestamptz,
  note text,
  avatar_descriptor jsonb,
  gallery_descriptors jsonb
)
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  if reviewer_uuid is null or not exists (
    select 1 from public.moderators where user_id = reviewer_uuid
  ) then
    raise exception using errcode = '42501', message = 'Current moderator membership is required';
  end if;
  perform public.approve_application_with_canonical_media(
    application_uuid, reviewer_uuid, expected_updated_at, note,
    avatar_descriptor, gallery_descriptors
  );
  perform private.append_privileged_audit(
    reviewer_uuid, 'application', application_uuid, 'approved_and_published',
    jsonb_build_object('after_status', 'approved')
  );
end;
$$;
revoke all on function public.approve_application_with_canonical_media_v2(uuid, uuid, timestamptz, text, jsonb, jsonb)
  from public, anon, authenticated;
grant execute on function public.approve_application_with_canonical_media_v2(uuid, uuid, timestamptz, text, jsonb, jsonb)
  to service_role;
revoke execute on function public.approve_application_with_canonical_media(uuid, uuid, timestamptz, text, jsonb, jsonb)
  from service_role;

